function e(e,t,n=5){let r=e.slice(0,n).map(e=>e.stats[t]).filter(e=>Number.isFinite(e));return r.length?r.reduce((e,t)=>e+t,0)/r.length:0}function t(e,t,n=.35){let r=e.map(e=>e.stats[t]).filter(e=>Number.isFinite(e));if(!r.length)return 0;let i=r.at(-1);for(let e=r.length-2;e>=0;e--)i=n*r[e]+(1-n)*i;return i}function n(n,r,i=5){let a={};for(let o of r)a[`${o}_avg_${i}`]=e(n,o,i),a[`${o}_ewm`]=t(n,o);return a}export{n as t};